sys_variable_value.value:
(function execute(inputs, outputs) {

    var start = new GlideDateTime(inputs.current_start_date);
    var today = new GlideDateTime(); // now, UTC

    var hasEnd = !!inputs.current_end_date;
    var durationMs = 0;

    if (hasEnd) {
        var end = new GlideDateTime(inputs.current_end_date);
        durationMs = end.getNumericValue() - start.getNumericValue();
    }

    var recurrence = (inputs.recurrence + '').toLowerCase().trim();

    var maxIterations = 1000;
    var iterations = 0;

    if (recurrence !== 'none' && recurrence !== '') {
        while (start.compareTo(today) < 0 && iterations < maxIterations) {
            switch (recurrence) {
                case 'weekly':
                    start.addDaysUTC(7);
                    break;
                case 'monthly':
                    start.addMonthsUTC(1);
                    break;
                case 'quarterly':
                    start.addMonthsUTC(3);
                    break;
                case 'yearly':
                    start.addYearsUTC(1);
                    break;
                default:
                    iterations = maxIterations;
                    break;
            }
            iterations++;
        }
    }

    outputs.next_start_date = start.getValue();

    if (hasEnd) {
        var newEnd = new GlideDateTime(start);
        newEnd.addSeconds(Math.round(durationMs / 1000));
        outputs.next_end_date = newEnd.getValue();
    }

})(inputs, outputs);

